// components/report/DownloadButton.tsx
export function DownloadButton({ reportId }) {
  const handleDownload = async () => {
    const response = await fetch(`/api/v1/report/${reportId}/download?format=png`);
    const blob = await response.blob();
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `itsmegram_report.png`;
    a.click();
  };

  return (
    <button onClick={handleDownload} className="...">
      <DownloadIcon /> 이미지 저장
    </button>
  );
}
