1. Instagram Share API 활용 (Web Share API + Instagram)
```tsx
// components/report/ShareButton.tsx
export function ShareToStoryButton({ imageUrl }) {
  const handleShare = async () => {
    // 모바일에서 Instagram 앱으로 공유
    if (navigator.share) {
      const response = await fetch(imageUrl);
      const blob = await response.blob();
      const file = new File([blob], 'itsmegram-report.png', { type: 'image/png' });

      await navigator.share({
        files: [file],
        title: 'My Instagram Analysis',
        text: 'itsmegram으로 분석한 나의 인스타그램 리포트!'
      });
    } else {
      // 폴백: 이미지 다운로드 후 안내
      alert('이미지가 저장되었습니다. Instagram 스토리에 직접 업로드해주세요!');
    }
  };

  return (
    <button onClick={handleShare} className="instagram-gradient ...">
      <InstagramIcon /> 스토리로 공유
    </button>
  );
}
```

