from fastapi import Request
from fastapi.responses import JSONResponse

@app.exception_handler(InstagramPrivateAccountError)
async def private_account_handler(request: Request, exc: InstagramPrivateAccountError):
    return JSONResponse(
        status_code=400,
        content={
            "error": "PRIVATE_ACCOUNT",
            "message": "비공개 계정은 분석할 수 없습니다",
            "suggestion": "계정을 공개로 변경 후 다시 시도해주세요"
        }
    )

@app.exception_handler(InstagramNotFoundError)
async def not_found_handler(request: Request, exc: InstagramNotFoundError):
    return JSONResponse(
        status_code=404,
        content={
            "error": "USER_NOT_FOUND",
            "message": "해당 사용자를 찾을 수 없습니다"
        }
    )

@app.exception_handler(RateLimitExceeded)
async def rate_limit_handler(request: Request, exc: RateLimitExceeded):
    return JSONResponse(
        status_code=429,
        content={
            "error": "RATE_LIMITED",
            "message": "너무 많은 요청이 발생했습니다. 잠시 후 다시 시도해주세요",
            "retry_after": 3600
        }
    )
