# backend/app/services/analytics_service.py
class AnalyticsService:
    async def track_event(self, event_name: str, properties: dict):
        event = {
            "event": event_name,
            "properties": properties,
            "timestamp": datetime.now().isoformat(),
            "distinct_id": properties.get("ip_hash")  # 익명화
        }
        # 데이터베이스 또는 로그로 저장
        await self.store_event(event)

    # 주요 이벤트
    async def track_page_view(self, page: str, referrer: str):
        await self.track_event("page_view", {"page": page, "referrer": referrer})

    async def track_analysis_start(self, username: str):
        await self.track_event("analysis_started", {"username_hash": hash(username)})

    async def track_analysis_complete(self, username: str, duration: float):
        await self.track_event("analysis_completed", {
            "username_hash": hash(username),
            "duration_seconds": duration
        })

    async def track_share(self, report_id: str, platform: str):
        await self.track_event("report_shared", {"platform": platform})
```

